import { tv, type VariantProps } from "@/lib/beton/tv";

export const ctaBand = tv({
  slots: {
    root: "w-full border-y-3 border-border",
    inner: "mx-auto flex w-full max-w-6xl flex-col gap-6 px-4 py-14 sm:px-6",
    title: "font-display text-h2 font-black tracking-tight text-balance",
    description: "max-w-prose text-pretty text-lg",
    actions: "flex flex-wrap items-center gap-4",
  },
  variants: {
    surface: {
      accent: { root: "bg-primary text-ink" },
      secondary: { root: "bg-secondary text-ink" },
      ink: { root: "bg-ink text-paper" },
      raised: { root: "bg-raised text-foreground" },
    },
    layout: {
      stacked: {},
      inline: { inner: "md:flex-row md:items-center md:justify-between" },
    },
  },
  defaultVariants: {
    surface: "accent",
    layout: "inline",
  },
});

export type CtaBandVariants = VariantProps<typeof ctaBand>;

import { ctaBand, type CtaBandVariants } from "@/lib/beton/recipes/cta-band.recipe";
import { useId, type ComponentProps, type ReactNode } from "react";

export interface CtaBandProps extends Omit<ComponentProps<"section">, "title">, CtaBandVariants {
  /** What you want people to do. */
  title: ReactNode;
  /** One line of reason. */
  description?: ReactNode;
  /** The buttons. */
  actions?: ReactNode;
  /** The heading level. Defaults to h2. */
  headingLevel?: 2 | 3;
}

/** A loud strip across the page with one thing to do. */
export function CtaBand({
  surface = "accent",
  layout = "inline",
  title,
  description,
  actions,
  headingLevel = 2,
  className,
  children,
  ...props
}: CtaBandProps) {
  const styles = ctaBand({ surface, layout });
  const id = useId();
  const Heading = `h${headingLevel}` as const;

  return (
    <section
      {...props}
      aria-labelledby={`${id}-title`}
      data-surface={surface}
      className={styles.root({ class: className })}
    >
      <div className={styles.inner()}>
        <div>
          <Heading id={`${id}-title`} className={styles.title()}>
            {title}
          </Heading>
          {description ? <p className={styles.description()}>{description}</p> : null}
        </div>
        {actions ? <div className={styles.actions()}>{actions}</div> : null}
        {children}
      </div>
    </section>
  );
}
